<script setup>
import { ref, reactive, computed } from 'vue'
const jobs = ref([{ id: 1, name: 'Daily application backup', schedule: '0 2 * * *', command: '/usr/local/bin/example-backup', user: 'www-data', enabled: true }, { id: 2, name: 'Prune example cache', schedule: '*/15 * * * *', command: 'php artisan cache:prune-stale-tags', user: 'www-data', enabled: false }])
const form = reactive({ name: '', schedule: '0 3 * * *', command: '', user: 'www-data' })
const error = ref(''), feedback = ref(''), query = ref(''), simulateFailure = ref(false)
const history = ref([{ job: 'Daily application backup', time: 'Example · 02:00:00 UTC', status: 'Completed · simulated', output: '[simulated] Example archive prepared. No process was started.', duration: '1.2s example' }])
const filtered = computed(() => jobs.value.filter(j => j.name.toLowerCase().includes(query.value.toLowerCase())))
function validSchedule(value) {
  const fields = value.trim().split(/\s+/), ranges = [[0,59],[0,23],[1,31],[1,12],[0,7]]
  return fields.length === 5 && fields.every((field, i) => field.split(',').every(part => {
    if (!/^(\*|\d+(?:-\d+)?)(?:\/\d+)?$/.test(part)) return false
    const [base, step] = part.split('/'); if (step && (+step < 1 || +step > ranges[i][1])) return false
    if (base === '*') return true
    const nums = base.split('-').map(Number); return nums.every(n => n >= ranges[i][0] && n <= ranges[i][1]) && (nums.length === 1 || nums[0] <= nums[1])
  }))
}
function createJob() {
  if (!form.name.trim() || !form.command.trim()) { error.value = 'Provide a job name and an example command.'; return }
  if (!validSchedule(form.schedule)) { error.value = 'Use a valid five-field cron expression (minute hour day month weekday).'; return }
  jobs.value.push({ ...form, id: Math.max(...jobs.value.map(j => j.id), 0) + 1, enabled: true }); error.value = ''; form.name = ''; form.command = ''; feedback.value = 'Preview only — example job added. No crontab was installed.'
}
function runJob(job) { history.value.unshift({ job: job.name, time: 'Just now · example', status: simulateFailure.value ? 'Failed · simulated' : 'Completed · simulated', output: simulateFailure.value ? '[simulated] Example exit code 1: permission denied. No command was executed.' : '[simulated] Example exit code 0. No command was executed.', duration: '0.4s example' }); feedback.value = 'Preview only — simulated history added; no process was started.' }
function toggleJob(job) { job.enabled = !job.enabled; feedback.value = 'Preview only — example schedule toggled. System cron remains unchanged.' }
</script>
<template>
  <main class="w-full pt-16 min-h-screen" style="background: rgb(var(--c-surface))">
    <section><header class="page-heading"><div><p class="ax-label">Automation / example schedules</p><h1>Cron Jobs</h1><p class="ax-sub">Design recurring tasks and inspect simulated run output.</p></div><span class="ax-pill ax-pill-dim">Schedule timezone · UTC</span></header><p v-if="feedback" class="notice ax-pill ax-pill-info" role="status">{{ feedback }}</p>
      <div class="cron-layout"><div><section class="ax-card"><div class="ax-card-pad ax-hd"><div><h2 class="ax-title">Scheduled tasks</h2><p class="ax-sub">Example data · commands are never executed.</p></div><label><span class="ax-label">Search jobs</span><input v-model="query" class="ax-input" type="search" placeholder="Filter examples"></label></div><div class="table-scroll"><table class="ax-table"><thead><tr><th>Job / command</th><th>Schedule · UTC</th><th>User</th><th>Enabled</th><th></th></tr></thead><tbody><tr v-for="job in filtered" :key="job.id"><td><strong>{{ job.name }}</strong><div class="ax-sub ax-mono">{{ job.command }}</div></td><td class="ax-mono">{{ job.schedule }}</td><td class="ax-mono">{{ job.user }}</td><td><button class="ax-toggle" :class="{ on: job.enabled }" role="switch" :aria-checked="job.enabled" :aria-label="'Toggle example schedule: ' + job.name + ' · Preview only'" @click="toggleJob(job)"></button></td><td><button class="ax-btn ax-btn-ghost" @click="runJob(job)"><span aria-hidden="true" class="material-symbols-outlined">play_arrow</span>Run · Preview only</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty">No matching example jobs. <button class="ax-btn ax-btn-ghost" @click="query = ''">Clear search</button></td></tr></tbody></table></div><footer class="panel-footer ax-sub">Toggles and manual runs affect example state only.</footer></section>
        <section class="ax-card history"><div class="ax-hd"><div><p class="ax-label">Simulation inspector</p><h2 class="ax-title">Run history</h2></div><label class="simulation"><input v-model="simulateFailure" type="checkbox">Simulate failure on next run</label></div><article v-for="(run, index) in history" :key="index" class="run"><div class="ax-hd"><strong>{{ run.job }}</strong><span class="ax-pill" :class="run.status.startsWith('Failed') ? 'ax-pill-err' : 'ax-pill-ok'">{{ run.status }}</span></div><p class="ax-sub ax-mono">{{ run.time }} · {{ run.duration }}</p><pre class="ax-code">{{ run.output }}</pre></article></section></div>
        <aside class="ax-card ax-card-pad"><p class="ax-label">Create schedule</p><h2 class="ax-title">New example job</h2><form @submit.prevent="createJob"><div class="ax-field"><label for="cron-name" class="ax-label">Job name</label><input id="cron-name" v-model="form.name" class="ax-input" placeholder="Daily cleanup" required></div><div class="ax-field"><label for="cron-preset" class="ax-label">Schedule preset</label><select id="cron-preset" v-model="form.schedule" class="ax-select"><option value="0 3 * * *">Every day at 03:00 UTC</option><option value="*/15 * * * *">Every 15 minutes</option><option value="0 0 * * 0">Every Sunday at 00:00 UTC</option><option :value="form.schedule">Custom expression</option></select></div><div class="ax-field"><label for="cron-schedule" class="ax-label">Cron expression</label><input id="cron-schedule" v-model="form.schedule" class="ax-input" required><p class="ax-sub ax-mono">minute · hour · day · month · weekday</p></div><div class="ax-field"><label for="cron-command" class="ax-label">Example command</label><textarea id="cron-command" v-model="form.command" class="ax-textarea" rows="3" placeholder="/usr/local/bin/example-task" required></textarea></div><div class="ax-field"><label for="cron-user" class="ax-label">Run as (example)</label><select id="cron-user" v-model="form.user" class="ax-select"><option>www-data</option><option>axion</option></select></div><p v-if="error" class="error" role="alert">{{ error }}</p><button class="ax-btn ax-btn-primary">Add schedule · Preview only</button></form><div class="ax-divider"></div><p class="ax-sub">Validation covers numeric five-field expressions only. No scheduler, shell, or host connection exists in this prototype.</p></aside>
      </div>
    </section>
  </main>
</template>
<style scoped>
.cron-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:20px}.history{padding:20px;margin-top:20px}.history h2{margin:4px 0}.run{padding:16px 0;border-top:1px solid rgb(var(--c-outline-variant)/.3)}.run strong,.simulation{font-size:12px}.simulation{display:flex;gap:8px;align-items:center;color:rgb(var(--c-on-surface-variant))}.ax-code{white-space:pre-wrap}.notice{margin-bottom:16px;white-space:normal}.error{color:rgb(var(--c-error));font-size:12px}aside form{margin-top:24px}.empty{text-align:center;padding:30px}.ax-toggle{min-height:20px}.ax-hd{flex-wrap:wrap}@media(max-width:1100px){.cron-layout{grid-template-columns:1fr}}button:focus-visible{outline:2px solid rgb(var(--c-primary));outline-offset:3px}
</style>
